663	  ObEvalCtx::BatchInfoScopeGuard batch_info_guard(eval_ctx_);
664	  while (OB_SUCC(ret)) {
665	    if (OB_FAIL(next_row())) {
666	      LOG_WARN("fetch next rows failed", K(ret));
667	      break;
668	    }
669	    if (dfc_.all_ch_drained()) {
670	      int tmp_ret = child_->drain_exch();
671	      if (OB_SUCCESS != tmp_ret) {
672	        LOG_WARN("drain exchange data failed", K(tmp_ret));
673	      }
674	      LOG_TRACE("all channel has been drained");
675	      break;
676	    }
677	    const ObPxTransmitSpec &spec = static_cast<const ObPxTransmitSpec &>(get_spec());
678	    batch_info_guard.set_batch_size(brs_.size_);
679	    if (OB_FAIL(ret) || brs_.size_ <= 0) {
680	    } else if (OB_FAIL(set_rollup_hybrid_keys(slice_calc))) {
681	      LOG_WARN("failed to set rollup hybrid keys", K(ret));
682	    } else if ((!slice_calc.support_vectorized_calc() || slice_calc.is_multi_slice_calc_type() || NULL != spec.tablet_id_expr_)) {
683	      for (int64_t i = 0; OB_SUCC(ret) && i < brs_.size_; i++) {
