693	          LOG_WARN("fail get slice idx", K(ret));
694	        } else if (NULL != spec.tablet_id_expr_
695	                   && OB_FAIL(slice_calc.get_previous_row_tablet_id(tablet_id))) {
696	          LOG_WARN("failed to get previous row tablet_id", K(ret));
697	        }
