699	        FOREACH_CNT_X(slice_idx, slice_idx_array, OB_SUCC(ret)) {
700	          if (OB_FAIL(send_row(*slice_idx, send_row_time_recorder, tablet_id.get_int()))) {
701	            LOG_WARN("fail emit row to interm result", K(ret), K(slice_idx_array));
702	          }
703	        }
704	      }
705	    } else {
706	      int64_t *indexes = NULL;
707	      if (OB_FAIL((slice_calc.get_slice_idx_batch<CALC_TYPE, false>(spec_.output_, eval_ctx_,
708	                                               *brs_.skip_, brs_.size_,
709	                                               indexes)))) {
710	        LOG_WARN("calc slice indexes failed", K(ret));
711	      } else {
712	        for (int64_t i = 0; OB_SUCC(ret) && i < brs_.size_; i++) {
713	          if (brs_.skip_->at(i) || indexes[i] < 0) { continue; }
714	            __builtin_prefetch(&blk_bufs_.at(indexes[i]),
715	                               0, // for read
