717	        }
718	        for (int64_t i = 0; OB_SUCC(ret) && i < brs_.size_; i++) {
719	          if (brs_.skip_->at(i) || indexes[i] < 0) { continue; }
720	          if (blk_bufs_.at(indexes[i]).is_inited()) {
721	            __builtin_prefetch(blk_bufs_.at(indexes[i]).head(),
722	                               1, // for write
723	                               1); // low temporal locality
724	          }
725	        }
